import React from "react";
import { FaChevronLeft, FaPaperPlane } from "react-icons/fa";
import { apiGet, apiPost } from "../common/api";
import Loader from "../common/Loader";
import withRouter from "../common/withRouter";

// صفحه‌ی چت پشتیبانی — وایر شده به GET /messages و POST /messages
class ChatSupportPage extends React.Component {
  constructor(props) {
    super(props);
    this.state = { messages: [], text: "", loading: true, sending: false };
    this.handleBack = this.handleBack.bind(this);
    this.handleTextChange = this.handleTextChange.bind(this);
    this.handleSend = this.handleSend.bind(this);
  }

  componentDidMount() {
    this.loadMessages();
  }

  loadMessages() {
    apiGet("/messages")
      .then((json) => {
        this.setState({ messages: json.messages || [], loading: false });
      })
      .catch(() => {
        this.setState({ loading: false });
      });
  }

  handleBack() {
    this.props.navigate(-1);
  }

  handleTextChange(e) {
    this.setState({ text: e.target.value });
  }

  handleSend(e) {
    e.preventDefault();
    const { text } = this.state;
    if (!text.trim()) return;

    this.setState({ sending: true });

    apiPost("/messages", { text })
      .then(() => {
        this.setState({ sending: false, text: "" });
        this.loadMessages();
      })
      .catch(() => {
        this.setState({ sending: false });
      });
  }

  render() {
    const { messages, text, loading, sending } = this.state;

    return (
      <div dir="rtl" lang="fa" className="bg-white min-vh-100 d-flex flex-column">
        {loading && <Loader />}

        <div className="d-flex align-items-center justify-content-between px-3 pt-4 pb-3 border-bottom" style={{ maxWidth: 480, margin: "0 auto", width: "100%" }}>
          <button
            type="button"
            onClick={this.handleBack}
            className="btn btn-light rounded-circle border p-2 d-flex align-items-center justify-content-center"
            style={{ width: 36, height: 36 }}
          >
            <FaChevronLeft size={14} />
          </button>
          <h1 className="fs-6 fw-semibold text-dark m-0">پشتیبانی</h1>
          <div style={{ width: 36 }} />
        </div>

        <div className="flex-grow-1 px-3 py-3 overflow-auto" style={{ maxWidth: 480, margin: "0 auto", width: "100%" }}>
          {messages.length === 0 && !loading ? (
            <div className="text-center text-muted py-5">هنوز پیامی وجود ندارد.</div>
          ) : (
            messages.map((m) => (
              <div key={m.id} className="mb-3 text-end">
                <div className="d-inline-block bg-light rounded-3 px-3 py-2">
                  {m.text}
                </div>
              </div>
            ))
          )}
        </div>

        <form
          onSubmit={this.handleSend}
          className="d-flex align-items-center gap-2 px-3 py-3 border-top"
          style={{ maxWidth: 480, margin: "0 auto", width: "100%" }}
        >
          <button type="submit" disabled={sending} className="btn btn-primary rounded-circle p-2 d-flex align-items-center justify-content-center" style={{ width: 40, height: 40 }}>
            <FaPaperPlane size={14} />
          </button>
          <input
            type="text"
            placeholder="پیام خود را بنویسید..."
            value={text}
            onChange={this.handleTextChange}
            className="form-control border rounded-pill text-end px-3 py-2"
          />
        </form>
      </div>
    );
  }
}

export default withRouter(ChatSupportPage);
